import { Lease, Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    // The lease is opened lazily, on the first iteration, and never read ahead:
    // every next() performs at most one read, the last one establishing exhaustion.
    let lease: Lease | undefined;
    let failure: unknown;
    let failed = false;
    try {
      lease = await this.source.open();
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // Remember the pending failure so a failing close cannot mask it.
      failed = true;
      failure = error;
      throw error;
    } finally {
      if (lease !== undefined) {
        try {
          await lease.close();
        } catch (closeError) {
          // Preserve the original read, mapper or injected exception when close
          // also fails; only surface a close failure on the success paths.
          if (!failed) {
            failed = true;
            failure = closeError;
            throw closeError;
          }
        }
      }
    }
  }
}
